import logging
import stripe
from agents import function_tool
logger = logging.getLogger(__name__)

class _RefundLog:

    def __init__(self, pi_id):
        self.pi_id = pi_id

    def __enter__(self):
        logger.info('starting refund for %s', self.pi_id)
        return self

    def __exit__(self, exc_type, exc, tb):
        if exc_type:
            logger.error('refund failed for %s: %s', self.pi_id, exc)
        else:
            logger.info('refund completed for %s', self.pi_id)
        return False

@function_tool
def issue_subscription_refund(payment_intent_id: str, amount_cents: int=0, reason: str='requested_by_customer') -> dict:
    with _RefundLog(payment_intent_id):
        args = {'payment_intent': payment_intent_id, 'reason': reason}
        if amount_cents and amount_cents > 0:
            args['amount'] = amount_cents
        refund = stripe.Refund.create(**args)
    if not (amount_cents and amount_cents > 0):
        # Full refund: revoke the customer's subscription access role
        pi = stripe.PaymentIntent.retrieve(payment_intent_id)
        if pi.get('customer'):
            stripe.Customer.modify(pi['customer'], metadata={'access_role': 'revoked'})
    return {'refund_id': refund['id'], 'status': refund['status'], 'amount': refund['amount'], 'currency': refund['currency']}
